        if(attempts.isEmpty()){if(prior)bad();var a=meta(input,now());a.put("write_id",str(row,"write_id"));a.put("intent_sha256",str(row,"intent_sha256"));insert("task_candidate_assembly_object_attempt",a);}else {verifyAttempt(input,row,one(attempts));prior=true;}
