    /** Fresh current input/source rights plus historical original author/approval journals.
     * A disabled producer may be read, but this path never creates an intent or PUT grant. */
    public Attempt recoverOriginal(TaskCandidateAssemblyAuthority.Verified input,String kind)throws Exception {
        var row=intent(input,kind);verifyIntent(input,kind,row);requireOriginal(input,kind,row);verifyAttempt(input,row,one(db.queryForList("SELECT * FROM task_candidate_assembly_object_attempt WHERE tenant_id=? AND write_id=? LIMIT 2 FOR UPDATE",input.production().tenantId(),str(row,"write_id"))));return new Attempt(row,true);
    }
    public void requireTransfer(TaskCandidateAssemblyAuthority.Verified input,TaskCandidateAssemblyProducerAuthority.Verified producer,Attempt attempt)throws Exception {producer.requireFor(input);producer.requireBytes(attempt.kind(),attempt.bytes().length);requireAttempt(input,attempt);if(!producer.canonicalPins().equals(json.read(str(attempt.row,"producer_pins_json"))))bad();}
    public void requireOriginalTransfer(TaskCandidateAssemblyAuthority.Verified input,Attempt attempt)throws Exception {if(!attempt.priorAttempt())deny();requireAttempt(input,attempt);requireOriginal(input,attempt.kind(),attempt.row);}
    private void requireOriginal(TaskCandidateAssemblyAuthority.Verified input,String kind,Map<String,Object> row)throws Exception {producers.requireOriginal(json.read(str(row,"producer_pins_json")),input,time(row.get("created_at")),kind,str(row,"canonical_payload").getBytes(StandardCharsets.UTF_8).length);}
    private void requireAttempt(TaskCandidateAssemblyAuthority.Verified input,Attempt attempt)throws Exception {
        if(attempt==null||attempt.owner!=this||!attempt.committed||attempt.thread!=Thread.currentThread())deny();var row=intent(input,attempt.kind());verifyIntent(input,attempt.kind(),row);if(!str(row,"intent_sha256").equals(str(attempt.row,"intent_sha256"))||!attempt.artifactId().equals(str(row,"artifact_id")))bad();verifyAttempt(input,row,one(db.queryForList("SELECT * FROM task_candidate_assembly_object_attempt WHERE tenant_id=? AND write_id=? LIMIT 2 FOR UPDATE",input.production().tenantId(),attempt.writeIntent().writeId())));
    }
    private void verifyAttempt(TaskCandidateAssemblyAuthority.Verified input,Map<String,Object> row,Map<String,Object> attempt){if(!str(row,"intent_sha256").equals(str(attempt,"intent_sha256"))||!input.production().actorId().equals(str(attempt,"created_by"))||!input.production().projectId().equals(str(attempt,"project_id"))||!schemaHash.equals(str(attempt,"schema_manifest_sha256")))bad();}
    private Map<String,Object> intent(TaskCandidateAssemblyAuthority.Verified input,String kind){var p=input.production();return one(db.queryForList("SELECT * FROM task_candidate_assembly_object_intent WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND kind=? LIMIT 2 FOR UPDATE",p.tenantId(),p.projectId(),p.runId(),input.stepId(),kind));}
